<?php if ($garden_license): $license=$garden_license; ?>
<section class="garden-panel garden-license-panel" id="license-usage" aria-labelledby="garden-license-title">
<div class="garden-panel-heading"><div><span class="garden-kicker">YOUR PLAN</span><h2 id="garden-license-title">License & usage</h2></div><span class="garden-pill"><?= htmlspecialchars(ucwords(strtolower(str_replace('_',' ',$license['status'])))); ?></span></div>
<div class="garden-license-meta"><strong><?= htmlspecialchars($license['plan_name'] ?: 'No active plan'); ?></strong><?php if ($license['end_date']): ?><span>Valid until <?= htmlspecialchars(date('j M Y',strtotime($license['end_date']))); ?> · <?= max(0,(int)$license['days_left']); ?> days remaining</span><?php endif; ?></div>
<div class="garden-license-grid"><?php foreach ($license['quotas'] as $quota): ?><div class="garden-license-card"><span><?= htmlspecialchars($quota['label']); ?></span><strong><?= number_format($quota['used'],$quota['unit']==='MB' ? 1 : 0); ?><?= $quota['unit']==='MB' ? ' MB' : ''; ?></strong><small><?= $quota['limit']>0 ? 'of '.number_format($quota['limit']).($quota['unit']==='MB' ? ' MB' : '').' included' : ($license['has_license'] ? 'No fixed limit' : 'No active limit'); ?></small><div class="garden-license-meter" aria-hidden="true"><i style="width:<?= max(0,min(100,(float)$quota['pct'])); ?>%" class="<?= $quota['pct']>=100 ? 'is-full' : ''; ?>"></i></div></div><?php endforeach; ?></div>
</section><?php endif; ?>
